// ──────────────────────────── tests ──────────────────────────────────────

test('all three flavors compute the same result', () => {
  eq(sumDeclaration(2, 3), 5);
  eq(sumExpression(2, 3), 5);
  eq(sumArrow(2, 3), 5);
});

test('each function picks up a name from its binding', () => {
  eq(sumDeclaration(1, 1), 2);
  eq(sumDeclaration.name, 'sumDeclaration');
  eq(sumExpression.name, 'sumExpression');
  eq(sumArrow.name, 'sumArrow');
});

test('length reports the declared parameter count', () => {
  eq(sumArrow(1, 1), 2);
  eq(sumDeclaration.length, 2);
  eq(sumExpression.length, 2);
  eq(sumArrow.length, 2);
});

test('only non-arrow functions carry a prototype object', () => {
  eq(sumExpression(4, 4), 8);
  eq(typeof sumDeclaration.prototype, 'object');
  eq(typeof sumExpression.prototype, 'object');
  eq(sumArrow.prototype, undefined);
});

test('an arrow cannot be called with new', () => {
  eq(sumArrow(0, 0), 0);
  let err = null;
  try {
    new sumArrow(1, 2);
  } catch (e) {
    err = e;
  }
  ok(err instanceof TypeError, 'new on an arrow should throw a TypeError');
});

test('a function declaration can be called with new', () => {
  eq(sumDeclaration(0, 0), 0);
  ok(new sumDeclaration(1, 2) instanceof sumDeclaration);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a function declaration can be called before its line', () => {
  eq(probeHoisting().declared, 'declared');
});

test('a declaration is already a function above its line', () => {
  eq(probeHoisting().typeofDeclared, 'function');
});

test('a const function expression is in the TDZ above its line', () => {
  eq(probeHoisting().expressed, 'ReferenceError');
});

test('a const arrow is in the TDZ too — arrows are not special', () => {
  eq(probeHoisting().arrowed, 'ReferenceError');
});

test('typeof does not protect you inside a TDZ', () => {
  eq(probeHoisting().typeofExpressed, 'ReferenceError');
});

test('the whole report has exactly the five expected keys', () => {
  eq(Object.keys(probeHoisting()).sort(), [
    'arrowed',
    'declared',
    'expressed',
    'typeofDeclared',
    'typeofExpressed',
  ]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('falls back to every default when only name is given', () => {
  eq(greet('Ada'), 'Hello, Ada!');
});

test('explicit arguments win over the defaults', () => {
  eq(greet('Ada', 'Yo', '?'), 'Yo, Ada?');
});

test('undefined picks the default but null does not', () => {
  eq(greet('Ada', undefined, undefined), 'Hello, Ada!');
  eq(greet('Ada', null), 'null, Ada!');
});

test('a default can be built from an earlier parameter', () => {
  eq(repeat('ab'), 'abab');
  eq(repeat('ab', 1), 'ab');
  eq(repeat('ab', 0), '');
});

test('pageRange defaults the page size to 10', () => {
  eq(pageRange(0), { from: 0, to: 9 });
  eq(pageRange(2), { from: 20, to: 29 });
  eq(pageRange(1, 5), { from: 5, to: 9 });
});

test('parameters with defaults do not count toward length', () => {
  eq(greet('Ada'), 'Hello, Ada!');
  eq(greet.length, 1);
  eq(repeat.length, 1);
  eq(pageRange.length, 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('each call that omits the bucket gets a fresh array', () => {
  const a = collect(1);
  const b = collect(2);
  eq(a, [1]);
  eq(b, [2]);
  ok(a !== b, 'the two calls must not share one array');
});

test('a bucket you pass in is reused, not replaced', () => {
  const bucket = collect('x');
  collect('y', bucket);
  eq(bucket, ['x', 'y']);
});

test('the default expression runs on every call that omits it', () => {
  const nextId = spy(() => 7);
  const record = makeRecorder(nextId);
  eq(record('a'), { id: 7, text: 'a' });
  eq(record('b'), { id: 7, text: 'b' });
  eq(nextId.callCount, 2);
});

test('the default expression is skipped when an id is given', () => {
  const nextId = spy(() => 7);
  const record = makeRecorder(nextId);
  eq(record('a', 99), { id: 99, text: 'a' });
  eq(nextId.callCount, 0);
});

test('the generator is called with no arguments', () => {
  const nextId = spy(() => 1);
  const record = makeRecorder(nextId);
  record('a');
  eq(nextId.calls, [[]]);
});

test('two recorders keep their own generators', () => {
  let n = 0;
  const record = makeRecorder(() => (n += 1));
  const other = makeRecorder(() => 100);
  eq(record('a').id, 1);
  eq(other('b').id, 100);
  eq(record('c').id, 2);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('sums any number of arguments', () => {
  eq(sumRest(1, 2, 3), 6);
  eq(sumRest(5), 5);
});

test('an empty rest list sums to zero', () => {
  eq(sumRest(), 0);
});

test('a rest parameter is a real array', () => {
  eq(tail('a', 'b', 'c'), ['b', 'c']);
  ok(Array.isArray(tail('a', 'b')), 'rest should be a genuine Array');
  eq(tail('a'), []);
});

test('rest parameters do not count toward length', () => {
  eq(sumRest(1), 1);
  eq(sumRest.length, 0);
  eq(tail.length, 1);
});

test('arguments holds every argument even with no parameters', () => {
  eq(argumentsInfo(1, 2, 3).count, 3);
  eq(argumentsInfo().count, 0);
  eq(argumentsInfo.length, 0);
});

test('arguments is array-like, not an array', () => {
  const info = argumentsInfo(1, 2, 3);
  eq(info.isArray, false);
  eq(info.asArray, [1, 2, 3]);
});

test('an arrow borrows the enclosing function arguments', () => {
  eq(firstViaArrow('a', 'b'), 'a');
  eq(firstViaArrow(42), 42);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a method call sets `this` to the object left of the dot', () => {
  const g = makeGauge('temp');
  eq(g.add(21), 1);
  eq(g.add(22), 2);
  eq(g.readings, [21, 22]);
  eq(g.label, 'temp');
});

test('two gauges keep separate readings', () => {
  const a = makeGauge('a');
  const b = makeGauge('b');
  a.add(1);
  b.add(2);
  eq(a.readings, [1]);
  eq(b.readings, [2]);
});

test('addAll keeps `this` inside its callback', () => {
  const g = makeGauge('temp');
  eq(g.addAll([1, 2, 3]), 3);
  eq(g.readings, [1, 2, 3]);
});

test('an arrow written as a method never gets the receiver', () => {
  const broken = makeBrokenGauge('temp');
  let err = null;
  try {
    broken.add(1);
  } catch (e) {
    err = e;
  }
  ok(err instanceof TypeError, 'the arrow method should blow up on `this`');
});

test('a method pulled off its object loses the receiver', () => {
  const g = makeGauge('temp');
  const loose = g.add;
  let err = null;
  try {
    loose(1);
  } catch (e) {
    err = e;
  }
  ok(err instanceof TypeError, 'a bare call has no receiver');
  eq(g.readings, []);
});

test('bind glues the receiver on permanently', () => {
  const g = makeGauge('temp');
  const other = makeGauge('other');
  const bound = bindAdd(g);
  bound(5);
  bound.bind(other)(6);
  eq(g.readings, [5, 6]);
  eq(other.readings, []);
});

test('a bound method survives being handed to forEach', () => {
  const g = makeGauge('temp');
  [1, 2].forEach(bindAdd(g));
  eq(g.readings, [1, 2]);
});

test('call or apply borrows the method for a single call', () => {
  const g = makeGauge('temp');
  eq(addWith(g, 7), 1);
  eq(addWith(g, 8), 2);
  eq(g.readings, [7, 8]);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns a new function, not the original', () => {
  const speak = () => 'hi';
  const bound = myBind(speak, null);
  ok(typeof bound === 'function');
  ok(bound !== speak, 'bind must not hand back the same function');
});

test('sets the receiver for the call', () => {
  const dog = { sound: 'woof', speak() { return this.sound; } };
  const speak = myBind(dog.speak, dog);
  eq(speak(), 'woof');
});

test('forwards the arguments it is called with', () => {
  const fn = spy((a, b) => a + b);
  const bound = myBind(fn, null);
  eq(bound(2, 3), 5);
  eq(fn.calls, [[2, 3]]);
});

test('puts preset arguments in front of the later ones', () => {
  const fn = spy((...args) => args);
  const bound = myBind(fn, null, 1, 2);
  eq(bound(3, 4), [1, 2, 3, 4]);
  eq(fn.calls, [[1, 2, 3, 4]]);
});

test('calls the original exactly once per call', () => {
  const fn = spy(() => 'x');
  const bound = myBind(fn, null);
  bound();
  bound();
  eq(fn.callCount, 2);
});

test('the receiver wins even when called as another object method', () => {
  const dog = { sound: 'woof', speak() { return this.sound; } };
  const cow = { sound: 'moo' };
  cow.speak = myBind(dog.speak, dog);
  eq(cow.speak(), 'woof');
});

test('a bound function cannot be rebound', () => {
  const dog = { sound: 'woof', speak() { return this.sound; } };
  const cow = { sound: 'moo' };
  const bound = myBind(dog.speak, dog);
  eq(bound.bind(cow)(), 'woof');
});

test('each bound function keeps its own presets', () => {
  const log = (level, msg) => `${level}: ${msg}`;
  const warn = myBind(log, null, 'WARN');
  const info = myBind(log, null, 'INFO');
  eq(warn('disk full'), 'WARN: disk full');
  eq(info('all good'), 'INFO: all good');
  eq(warn('again'), 'WARN: again');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('counts up from zero by default', () => {
  const next = makeCounter();
  eq(next(), 1);
  eq(next(), 2);
  eq(next(), 3);
});

test('starts counting after the given value', () => {
  const page = makeCounter(10);
  eq(page(), 11);
  eq(page(), 12);
});

test('two counters do not share their state', () => {
  const a = makeCounter();
  const b = makeCounter(100);
  eq(a(), 1);
  eq(b(), 101);
  eq(a(), 2);
  eq(b(), 102);
});

test('the counter is a function, not an object', () => {
  const next = makeCounter();
  ok(typeof next === 'function');
  next();
  next();
  eq(next(), 3);
});

test('the accumulator keeps a running total', () => {
  const total = makeAccumulator();
  eq(total(5), 5);
  eq(total(3), 8);
  eq(total(-8), 0);
});

test('two accumulators keep separate totals', () => {
  const a = makeAccumulator();
  const b = makeAccumulator();
  eq(a(2), 2);
  eq(b(10), 10);
  eq(a(2), 4);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('starts at the opening balance', () => {
  eq(createAccount(50).getBalance(), 50);
  eq(createAccount().getBalance(), 0);
});

test('deposits add to the balance and return it', () => {
  const acct = createAccount(10);
  eq(acct.deposit(15), 25);
  eq(acct.deposit(5), 30);
  eq(acct.getBalance(), 30);
});

test('withdrawals subtract from the balance', () => {
  const acct = createAccount(100);
  eq(acct.withdraw(30), 70);
  eq(acct.getBalance(), 70);
});

test('refuses to overdraw', () => {
  const acct = createAccount(50);
  throws(() => acct.withdraw(51), 'Insufficient funds');
  eq(acct.getBalance(), 50);
});

test('exposes only the three methods', () => {
  const acct = createAccount(50);
  eq(Object.keys(acct).sort(), ['deposit', 'getBalance', 'withdraw']);
  eq(acct.balance, undefined);
});

test('an outside property cannot corrupt the real balance', () => {
  const acct = createAccount(50);
  acct.balance = 999999;
  eq(acct.getBalance(), 50);
  eq(acct.withdraw(50), 0);
});

test('two accounts keep separate balances', () => {
  const a = createAccount(10);
  const b = createAccount(10);
  a.deposit(5);
  eq(a.getBalance(), 15);
  eq(b.getBalance(), 10);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns a function', () => {
  const guarded = once(() => 1);
  ok(typeof guarded === 'function');
});

test('runs the wrapped function on the first call only', () => {
  const fn = spy(() => 'ok');
  const guarded = once(fn);
  guarded();
  guarded();
  guarded();
  eq(fn.callCount, 1);
});

test('hands back the first result every time', () => {
  let n = 0;
  const guarded = once(() => (n += 1));
  eq(guarded(), 1);
  eq(guarded(), 1);
  eq(guarded(), 1);
});

test('forwards the first call arguments', () => {
  const fn = spy((host, port) => `${host}:${port}`);
  const guarded = once(fn);
  eq(guarded('db', 5432), 'db:5432');
  eq(fn.calls, [['db', 5432]]);
});

test('ignores the arguments of later calls', () => {
  const fn = spy((label) => label);
  const guarded = once(fn);
  eq(guarded('first'), 'first');
  eq(guarded('second'), 'first');
  eq(fn.callCount, 1);
});

test('caches an undefined result instead of re-running', () => {
  const fn = spy(() => undefined);
  const guarded = once(fn);
  eq(guarded(), undefined);
  eq(guarded(), undefined);
  eq(fn.callCount, 1);
});

test('each wrapper has its own state', () => {
  const fn = spy((x) => x);
  const a = once(fn);
  const b = once(fn);
  eq(a('a'), 'a');
  eq(b('b'), 'b');
  eq(a('again'), 'a');
  eq(fn.callCount, 2);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('numbers ids from one', () => {
  const nextId = makeIdGenerator();
  eq(nextId(), 'id-1');
  eq(nextId(), 'id-2');
  eq(nextId(), 'id-3');
});

test('uses the prefix you pass', () => {
  const nextUser = makeIdGenerator('user');
  eq(nextUser(), 'user-1');
  eq(nextUser(), 'user-2');
});

test('produces strings', () => {
  const nextId = makeIdGenerator();
  ok(typeof nextId() === 'string');
});

test('two generators count independently', () => {
  const a = makeIdGenerator('a');
  const b = makeIdGenerator('b');
  eq(a(), 'a-1');
  eq(b(), 'b-1');
  eq(a(), 'a-2');
  eq(b(), 'b-2');
});

test('keeps counting over many calls', () => {
  const nextId = makeIdGenerator('row');
  const ids = [1, 2, 3, 4, 5].map(() => nextId());
  eq(ids, ['row-1', 'row-2', 'row-3', 'row-4', 'row-5']);
});

test('produces no duplicates', () => {
  const nextId = makeIdGenerator();
  const ids = [1, 2, 3, 4].map(() => nextId());
  eq(new Set(ids).size, 4);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('var shares one binding, so every function reports 3', () => {
  const fns = brokenWithVar();
  eq(fns.length, 3);
  eq(fns.map((f) => f()), [3, 3, 3]);
});

test('the broken version really is written with var', () => {
  brokenWithVar();
  ok(/\bvar\b/.test(brokenWithVar.toString()), 'expected a var loop');
});

test('let gives every iteration its own binding', () => {
  eq(fixedWithLet().map((f) => f()), [0, 1, 2]);
});

test('an IIFE copies the value into a fresh scope', () => {
  eq(fixedWithIIFE().map((f) => f()), [0, 1, 2]);
});

test('the IIFE version still uses var for the counter', () => {
  fixedWithIIFE();
  ok(/\bvar\b/.test(fixedWithIIFE.toString()), 'keep the var loop');
});

test('the fixed functions can be called in any order', () => {
  const fns = fixedWithLet();
  eq(fns[2](), 2);
  eq(fns[0](), 0);
  eq(fns[1](), 1);
  eq(fns[0](), 0);
});

test('both fixes agree with each other', () => {
  eq(
    fixedWithLet().map((f) => f()),
    fixedWithIIFE().map((f) => f())
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

test('multiplierOf returns a multiplying function', () => {
  const double = multiplierOf(2);
  ok(typeof double === 'function');
  eq(double(5), 10);
  eq(double(0), 0);
});

test('every multiplier remembers its own factor', () => {
  const double = multiplierOf(2);
  const triple = multiplierOf(3);
  eq(double(4), 8);
  eq(triple(4), 12);
  eq(double(4), 8);
});

test('a multiplier drops straight into map', () => {
  eq([1, 2, 3].map(multiplierOf(3)), [3, 6, 9]);
});

test('prefixer joins with a space by default', () => {
  const debug = prefixer('DEBUG');
  eq(debug('starting'), 'DEBUG starting');
  eq(debug('done'), 'DEBUG done');
});

test('prefixer accepts a custom separator', () => {
  eq(prefixer('v', '')('2.1'), 'v2.1');
  eq(prefixer('a', '-')('b'), 'a-b');
});

test('propertyGetter reads one key out of any object', () => {
  const name = propertyGetter('name');
  eq(name({ name: 'Ada', age: 36 }), 'Ada');
  eq(name({ name: 'Grace' }), 'Grace');
});

test('propertyGetter is a ready-made map callback', () => {
  const users = [{ id: 1 }, { id: 2 }, { id: 3 }];
  eq(users.map(propertyGetter('id')), [1, 2, 3]);
  eq(propertyGetter('missing')({}), undefined);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a valid value produces no messages', () => {
  eq(makeValidator(passwordRules)('Str0ngEnough'), []);
});

test('collects every failing message in rule order', () => {
  eq(makeValidator(passwordRules)('abc'), [
    'too short',
    'needs a digit',
    'needs a capital',
  ]);
});

test('reports only the rules that actually fail', () => {
  eq(makeValidator(passwordRules)('abcdefgh'), [
    'needs a digit',
    'needs a capital',
  ]);
  eq(makeValidator(passwordRules)('abcdefg1'), ['needs a capital']);
});

test('an empty rule list accepts everything', () => {
  const check = makeValidator([]);
  eq(check('anything'), []);
  eq(check(''), []);
});

test('one validator can be reused for many values', () => {
  const check = makeValidator(passwordRules);
  eq(check('Str0ngEnough'), []);
  eq(check('abcdefg1'), ['needs a capital']);
  eq(check('Str0ngEnough'), []);
});

test('every rule is tested with the value, once', () => {
  const rule = spy(() => true);
  const check = makeValidator([{ message: 'nope', test: rule }]);
  check('hello');
  eq(rule.calls, [['hello']]);
});

test('validators built from different rules stay independent', () => {
  const strict = makeValidator(passwordRules);
  const loose = makeValidator([passwordRules[0]]);
  eq(loose('abc'), ['too short']);
  eq(strict('abc').length, 3);
});

frozen.body:
const passwordRules = [
  { message: 'too short', test: (v) => v.length >= 8 },
  { message: 'needs a digit', test: (v) => /\d/.test(v) },
  { message: 'needs a capital', test: (v) => /[A-Z]/.test(v) },
];

