// ──────────────────────────── tests ──────────────────────────────────────

test('a fresh board is empty', () => {
  taskBoard.reset();
  eq(taskBoard.list(), []);
  eq(taskBoard.stats(), { total: 0, done: 0, open: 0 });
});

test('add returns the stored task with an incrementing id', () => {
  taskBoard.reset();
  eq(taskBoard.add('write tests'), {
    id: 1,
    title: 'write tests',
    done: false,
  });
  eq(taskBoard.add('ship it'), { id: 2, title: 'ship it', done: false });
});

test('list reports the tasks in insertion order', () => {
  taskBoard.reset();
  taskBoard.add('first');
  taskBoard.add('second');
  eq(
    taskBoard.list().map((t) => t.title),
    ['first', 'second']
  );
});

test('complete marks a task done and reports success', () => {
  taskBoard.reset();
  taskBoard.add('write tests');
  eq(taskBoard.complete(1), true);
  eq(taskBoard.list()[0].done, true);
});

test('completing an unknown id changes nothing', () => {
  taskBoard.reset();
  taskBoard.add('write tests');
  eq(taskBoard.complete(99), false);
  eq(taskBoard.list()[0].done, false);
});

test('list hands out a copy, not the private array', () => {
  taskBoard.reset();
  taskBoard.add('only one');
  const copy = taskBoard.list();
  copy.push({ id: 99, title: 'injected', done: false });
  eq(copy.length, 2);
  eq(taskBoard.list().length, 1);
});

test('stats counts done and open separately', () => {
  taskBoard.reset();
  taskBoard.add('a');
  taskBoard.add('b');
  taskBoard.add('c');
  taskBoard.complete(2);
  eq(taskBoard.stats(), { total: 3, done: 1, open: 2 });
});

test('the state is private and reset restarts the ids', () => {
  taskBoard.reset();
  eq(Object.keys(taskBoard).sort(), [
    'add',
    'complete',
    'list',
    'reset',
    'stats',
  ]);
  taskBoard.add('a');
  ok(taskBoard.tasks === undefined, 'the task list must not be a property');
  taskBoard.reset();
  eq(taskBoard.add('fresh').id, 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('computes once per argument inside the window', () => {
  let clock = 0;
  const fn = spy((k) => `v:${k}`);
  const cached = memoizeTtl(fn, 100, () => clock);
  eq(cached('a'), 'v:a');
  clock = 60;
  eq(cached('a'), 'v:a');
  eq(fn.callCount, 1);
});

test('recomputes once the entry is older than the ttl', () => {
  let clock = 0;
  const fn = spy((k) => `${k}${clock}`);
  const cached = memoizeTtl(fn, 100, () => clock);
  eq(cached('a'), 'a0');
  clock = 150;
  eq(cached('a'), 'a150');
  eq(fn.callCount, 2);
});

test('an entry exactly ttlMs old counts as stale', () => {
  let clock = 0;
  const fn = spy(() => 1);
  const cached = memoizeTtl(fn, 100, () => clock);
  cached('a');
  clock = 100;
  cached('a');
  eq(fn.callCount, 2);
});

test('a recompute re-stamps the entry', () => {
  let clock = 0;
  const fn = spy(() => 1);
  const cached = memoizeTtl(fn, 100, () => clock);
  cached('a');
  clock = 100;
  cached('a');
  clock = 180;
  cached('a');
  eq(fn.callCount, 2, 'the entry stored at 100 is still fresh at 180');
});

test('caches falsy and undefined results instead of recomputing', () => {
  let clock = 0;
  const zero = spy(() => 0);
  const cachedZero = memoizeTtl(zero, 100, () => clock);
  eq(cachedZero('a'), 0);
  eq(cachedZero('a'), 0);
  eq(zero.callCount, 1);

  const nothing = spy(() => undefined);
  const cachedNothing = memoizeTtl(nothing, 100, () => clock);
  eq(cachedNothing('a'), undefined);
  eq(cachedNothing('a'), undefined);
  eq(nothing.callCount, 1);
});

test('each argument gets its own entry and its own clock stamp', () => {
  let clock = 0;
  const fn = spy((k) => k);
  const cached = memoizeTtl(fn, 100, () => clock);
  cached('a');
  clock = 50;
  cached('b');
  clock = 120;
  cached('a');
  cached('b');
  eq(fn.calls, [['a'], ['b'], ['a']], 'b was stored at 50, still fresh');
});

test('falls back to a real clock when none is injected', () => {
  const fn = spy((k) => k.toUpperCase());
  const cached = memoizeTtl(fn, 60_000);
  eq(cached('a'), 'A');
  eq(cached('a'), 'A');
  eq(fn.callCount, 1);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('lets the first `limit` calls through', () => {
  const allow = makeRateLimiter(3, 100, () => 0);
  eq([allow(), allow(), allow()], [true, true, true]);
});

test('blocks once the window is full', () => {
  const allow = makeRateLimiter(2, 100, () => 0);
  allow();
  allow();
  eq(allow(), false);
  eq(allow(), false);
});

test('lets a call through once the oldest one slides out', () => {
  let clock = 0;
  const allow = makeRateLimiter(2, 100, () => clock);
  allow();
  clock = 40;
  allow();
  clock = 90;
  eq(allow(), false, 'both hits are still inside the window');
  clock = 100;
  eq(allow(), true, 'the hit from 0 has aged out');
});

test('a blocked call is not recorded', () => {
  let clock = 0;
  const allow = makeRateLimiter(1, 100, () => clock);
  eq(allow(), true);
  clock = 50;
  eq(allow(), false);
  clock = 100;
  eq(allow(), true, 'the rejected call at 50 must not hold the slot');
});

test('a timestamp exactly windowMs old is outside the window', () => {
  let clock = 0;
  const allow = makeRateLimiter(1, 100, () => clock);
  allow();
  clock = 99;
  eq(allow(), false);
  clock = 100;
  eq(allow(), true);
});

test('the window slides, it does not tick over in fixed buckets', () => {
  let clock = 0;
  const allow = makeRateLimiter(2, 100, () => clock);
  allow();
  clock = 60;
  allow();
  clock = 110;
  eq(allow(), true, 'only the hit from 0 has aged out');
  eq(allow(), false, 'the hit from 60 still holds the second slot');
});

test('two limiters keep separate histories', () => {
  const clock = () => 0;
  const a = makeRateLimiter(1, 100, clock);
  const b = makeRateLimiter(1, 100, clock);
  eq(a(), true);
  eq(b(), true);
  eq(a(), false);
});

test('reads the clock on every call', () => {
  const clock = spy(() => 0);
  const allow = makeRateLimiter(5, 100, clock);
  allow();
  allow();
  ok(clock.callCount >= 2, 'the time must be sampled per call');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a toggle starts off and reports the state after flipping', () => {
  const dark = makeToggle();
  eq(dark(), true);
  eq(dark(), false);
  eq(dark(), true);
});

test('a toggle can be started on', () => {
  const dark = makeToggle(true);
  eq(dark(), false);
  eq(dark(), true);
});

test('two toggles hold separate state', () => {
  const a = makeToggle();
  const b = makeToggle();
  a();
  a();
  eq(a(), true);
  eq(b(), true, 'b has only just been flipped for the first time');
});

test('cycle hands back the values in order, starting at the first', () => {
  const dir = cycle('N', 'E', 'S');
  eq([dir(), dir(), dir()], ['N', 'E', 'S']);
});

test('cycle wraps around forever', () => {
  const dir = cycle('N', 'E');
  eq([dir(), dir(), dir(), dir(), dir()], ['N', 'E', 'N', 'E', 'N']);
});

test('a one-value cycle keeps returning that value', () => {
  const only = cycle('N');
  eq([only(), only(), only()], ['N', 'N', 'N']);
});

test('an empty cycle returns undefined instead of blowing up', () => {
  const nothing = cycle();
  eq(nothing(), undefined);
  eq(nothing(), undefined);
});

test('two cycles over the same values keep separate positions', () => {
  const values = ['a', 'b', 'c'];
  const one = cycle(...values);
  const two = cycle(...values);
  one();
  one();
  eq(one(), 'c');
  eq(two(), 'a');
  ok(values.length === 3, 'the source array must not be consumed');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('returns a function that carries a reset method', () => {
  const boot = onceWithReset(() => 1);
  ok(typeof boot === 'function');
  ok(typeof boot.reset === 'function');
});

test('runs the wrapped function once until it is reset', () => {
  const fn = spy(() => 'connected');
  const boot = onceWithReset(fn);
  eq(boot(), 'connected');
  eq(boot(), 'connected');
  eq(fn.callCount, 1);
});

test('reset opens the guard again', () => {
  let n = 0;
  const boot = onceWithReset(() => (n += 1));
  eq(boot(), 1);
  eq(boot(), 1);
  boot.reset();
  eq(boot(), 2);
  eq(boot(), 2);
});

test('the first call after a reset supplies the arguments', () => {
  const fn = spy((label) => label);
  const boot = onceWithReset(fn);
  eq(boot('first'), 'first');
  eq(boot('ignored'), 'first');
  boot.reset();
  eq(boot('second'), 'second');
  eq(fn.calls, [['first'], ['second']]);
});

test('reset clears the cached result, even when it was undefined', () => {
  const fn = spy(() => undefined);
  const boot = onceWithReset(fn);
  eq(boot(), undefined);
  eq(boot(), undefined);
  eq(fn.callCount, 1);
  boot.reset();
  eq(boot(), undefined);
  eq(fn.callCount, 2);
});

test('resetting before the first call changes nothing', () => {
  const fn = spy(() => 'ok');
  const boot = onceWithReset(fn);
  boot.reset();
  eq(boot(), 'ok');
  eq(boot(), 'ok');
  eq(fn.callCount, 1);
});

test('each wrapper resets independently', () => {
  const fn = spy((x) => x);
  const a = onceWithReset(fn);
  const b = onceWithReset(fn);
  a('a');
  b('b');
  a.reset();
  a('a again');
  eq(b('b again'), 'b', 'resetting a must not touch b');
  eq(fn.callCount, 3);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('sumTo adds up the whole numbers up to n', () => {
  eq(sumTo(4), 10);
  eq(sumTo(1), 1);
});

test('sumTo bottoms out at zero', () => {
  eq(sumTo(0), 0);
});

test('sumTo recurses through its own name, which stays private', () => {
  eq(sumTo(3), 6);
  eq(sumTo.name, 'total', 'the expression must be named `total`');
  eq(typeof globalThis.total, 'undefined', '`total` must not leak out');
});

test('countLeaves counts the leaves of a nested tree', () => {
  eq(tree.countLeaves(oak), 2);
});

test('a childless node is itself one leaf', () => {
  eq(tree.countLeaves({ name: 'solo', children: [] }), 1);
});

test('the method survives being detached from the object', () => {
  const detached = tree.countLeaves;
  const original = tree.countLeaves;
  tree.countLeaves = null;
  try {
    eq(detached(oak), 2, 'recursion must not go through `tree` or `this`');
  } finally {
    tree.countLeaves = original;
  }
});

test('the method carries its own name, not the property name', () => {
  eq(tree.countLeaves(oak), 2);
  eq(tree.countLeaves.name, 'walk', 'the expression must be named `walk`');
});

