  eq(curry(tag)(_, _, 'slow')('WARN')('db'), '[WARN] db: slow');
  eq(curry(tag)(_, 'db', _)('WARN', 'slow'), '[WARN] db: slow');
});

test('nothing runs until every slot holds a real value', () => {
  const fn = spy((a, b, c) => a + b + c);
  const curried = curry(fn, 3); // a spy forwards ...args, so arity 0
  const partial = curried(1)(_, 3);
  eq(fn.callCount, 0);
  eq(partial(2), 6);
  eq(fn.calls, [[1, 2, 3]]);
});

test('a partially applied stage can be reused', () => {
  const add = curry((a, b) => a + b);
  const add10 = add(10);
  eq(add10(1), 11);
  eq(add10(2), 12);
  eq(add10(3), 13);
});

test('arguments past the arity are dropped', () => {
  const fn = spy((a, b, c) => [a, b, c]);
  eq(curry(fn, 3)('a', 'b', 'c', 'd'), ['a', 'b', 'c']);
  eq(fn.calls, [['a', 'b', 'c']]);
});

test('the arity can be given for a variadic function', () => {
  const count = spy((...xs) => xs.length);
  ok(count.length === 0, 'a rest parameter reports arity 0');
  eq(curry(count, 2)('a')('b'), 2);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('overload picks the handler for the number of arguments', () => {
  const at = overload({
    1: (i) => `row ${i}`,
    2: (i, j) => `cell ${i},${j}`,
  });
  eq(at(3), 'row 3');
  eq(at(1, 2), 'cell 1,2');
});

test('the handler receives the arguments as they were passed', () => {
  const one = spy(() => 'one');
  const two = spy(() => 'two');
  const at = overload({ 1: one, 2: two });
  at('a');
  at('a', 'b');
  eq(one.calls, [['a']]);
  eq(two.calls, [['a', 'b']]);
});

test('an explicitly passed undefined still counts as an argument', () => {
  const at = overload({
    0: () => 'nothing',
    1: (x) => `got ${x}`,
  });
  eq(at(), 'nothing');
  eq(at(undefined), 'got undefined');
});

test('an unsupported count throws a TypeError that says so', () => {
  const at = overload({ 1: (x) => x });
  throws(() => at(1, 2, 3), 'no overload for 3 arguments');
  let caught;
  try { at(1, 2, 3); } catch (e) { caught = e; }
  ok(caught instanceof TypeError, 'specifically a TypeError');
});

test('list with no second argument copies everything', () => {
  const all = list(nums);
  eq(all, [1, 2, 3, 4]);
  ok(all !== nums, 'a copy, so the caller cannot mutate the source');
});

test('a number means "the first n"', () => {
  eq(list(nums, 2), [1, 2]);
  eq(list(nums, 0), [], 'zero means none, not everything');
});

test('a function means "the ones that pass"', () => {
  eq(list(nums, (n) => n > 2), [3, 4]);
  eq(list(nums, (n) => n > 99), []);
});

test('an object means options: filter first, then cap', () => {
  eq(list(nums, { where: (n) => n % 2 === 0 }), [2, 4]);
  eq(list(nums, { where: (n) => n > 1, limit: 2 }), [2, 3]);
  eq(list(nums, { limit: 1 }), [1]);
});

