test('two recorders keep their own generators', () => {
  let n = 0;
  const record = makeRecorder(() => (n += 1));
  const other = makeRecorder(() => 100);
  eq(record('a').id, 1);
  eq(other('b').id, 100);
  eq(record('c').id, 2);
});

