  eq(taskBoard.list()[0].done, true);
});

test('completing an unknown id changes nothing', () => {
  taskBoard.reset();
  taskBoard.add('write tests');
  eq(taskBoard.complete(99), false);
  eq(taskBoard.list()[0].done, false);
});

