  const join = (...parts) => parts.join('-');
  const toCsv = partialRight(join, 'csv');
  const toTsv = partialRight(join, 'tsv');
  eq(toCsv('report'), 'report-csv');
  eq(toTsv('report'), 'report-tsv');
});

