const crew = [
  { name: 'ada', age: 36 },
  { name: 'lin', age: 28 },
  { name: 'grace', age: 45 },
];

// ──────────────────────────── tests ──────────────────────────────────────

test('by sorts on a numeric key, smallest first', () => {
  eq(
    [...crew].sort(by('age')).map((p) => p.age),
    [28, 36, 45]
  );
});

test('by sorts on a string key too', () => {
