  const store = createStore({ user: 'ada', theme: 'dark' });
  eq(store.get(), { user: 'ada', theme: 'dark' });
  eq(createStore().get(), {});
});

test('set merges the patch instead of replacing the state', () => {
  const store = createStore({ user: 'ada', theme: 'dark' });
  store.set({ theme: 'light' });
  eq(store.get(), { user: 'ada', theme: 'light' });
});

