  eq(isEven(0), true);
  eq(isEven(3), false);
  eq(isEven(4), true);
});

test('isOdd answers for the small cases', () => {
  eq(isOdd(0), false);
  eq(isOdd(3), true);
  eq(isOdd(4), false);
});

